import React, { useState } from 'react';
import ResetPasswordModal from './ResetPasswordModal';

export default function StudentDashboard({ userName, handleLogout, grade, subjects }) {
  const [showResetModal, setShowResetModal] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  
  const studentGrade = grade || 'Grade 9';
  const studentSubject = subjects || 'ICT';

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <>
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '30px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <h1 style={{ margin: '0 0 10px 0' }}>Welcome back, {userName}! 👋</h1>
                  <p style={{ margin: 0, opacity: 0.9 }}>Your Interactive Learning Portal is ready.</p>
                </div>
                {/* ⭐ Star Badges Section (From SRS) */}
                <div style={{ backgroundColor: 'rgba(255,255,255,0.2)', padding: '15px', borderRadius: '10px', textAlign: 'center' }}>
                  <h3 style={{ margin: '0 0 5px 0', color: '#facc15' }}>⭐⭐⭐</h3>
                  <p style={{ margin: 0, fontSize: '14px', fontWeight: 'bold' }}>3 Star Badges Earned!</p>
                </div>
              </div>
            </div>

            {/* 📊 Progress Tracking Bar (From SRS) */}
            <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', marginBottom: '30px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
              <h3 style={{ margin: '0 0 15px 0', color: '#1e293b' }}>Course Progress: {studentGrade} {studentSubject}</h3>
              <div style={{ width: '100%', backgroundColor: '#e2e8f0', borderRadius: '10px', height: '15px', overflow: 'hidden' }}>
                <div style={{ width: '65%', backgroundColor: '#15803d', height: '100%', borderRadius: '10px' }}></div>
              </div>
              <p style={{ margin: '10px 0 0 0', color: '#64748b', fontSize: '14px', textAlign: 'right' }}>65% Completed</p>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '20px' }}>
              <DashboardCard title="Video Lessons" count="12" icon="▶️" color="#eff6ff" textColor="#1d4ed8" />
              <DashboardCard title="PDF Handouts" count="08" icon="📄" color="#f0fdf4" textColor="#15803d" />
              <DashboardCard title="Completed Activities" count="05" icon="✅" color="#fefce8" textColor="#a16207" />
            </div>
          </>
        );

      case 'lessons':
        return (
          <div>
            <h2>📺 Video Lessons & PDF Notes</h2>
            {/* Split-screen layout concept from SRS */}
            <div style={{ display: 'flex', gap: '20px', marginTop: '15px' }}>
                <div style={{ flex: 2, backgroundColor: 'black', height: '300px', borderRadius: '15px', display: 'flex', justifyContent: 'center', alignItems: 'center', color: 'white' }}>
                    ▶️ YouTube Video Player Area
                </div>
                <div style={{ flex: 1, backgroundColor: 'white', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
                    <h3 style={{ marginTop: 0 }}>Lesson Materials</h3>
                    <button style={actionBtnStyle}>📄 Download PDF Handout</button>
                    <button style={{...actionBtnStyle, backgroundColor: '#facc15', color: '#1e293b', marginTop: '10px'}}>📝 Take MCQ Quiz</button>
                </div>
            </div>
          </div>
        );

      case 'activities':
        return (
          <div>
            <h2>🎮 Interactive Learning Module</h2>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginTop: '15px' }}>
                <div style={activityCardStyle}>
                    <h3 style={{ margin: '0 0 10px 0' }}>🧩 Matching Game</h3>
                    <p style={{ color: '#64748b', fontSize: '14px' }}>Match the IT terms with their definitions.</p>
                    <button style={actionBtnStyle}>Start Game</button>
                </div>
                <div style={activityCardStyle}>
                    <h3 style={{ margin: '0 0 10px 0' }}>✍️ Fill-in-the-Blanks</h3>
                    <p style={{ color: '#64748b', fontSize: '14px' }}>Complete the sentences based on Lesson 3.</p>
                    <button style={actionBtnStyle}>Start Activity</button>
                </div>
            </div>
          </div>
        );

      default: return null;
    }
  };

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f4f7f6', fontFamily: 'sans-serif' }}>
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '25px 0', display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
            <h2 style={{ margin: 0, fontSize: '22px' }}>Aura Pen Saku</h2>
            <p style={{ color: '#bbf7d0', margin: '5px 0 0 0', fontSize: '12px' }}>Student LMS Portal</p>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '0 15px' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard" />
          <SidebarBtn active={activeTab === 'lessons'} onClick={() => setActiveTab('lessons')} icon="📺" text="My Lessons" />
          <SidebarBtn active={activeTab === 'activities'} onClick={() => setActiveTab('activities')} icon="🎮" text="Interactive Activities" />
          <SidebarBtn active={false} onClick={() => setShowResetModal(true)} icon="🔑" text="Change Password" />
        </div>
        <div style={{ marginTop: 'auto', padding: '0 15px' }}><button onClick={handleLogout} style={logoutBtnStyle}>Logout</button></div>
      </div>
      <div style={{ flex: 1, padding: '40px 50px' }}>{renderContent()}</div>
      {showResetModal && <ResetPasswordModal userName={userName} role="student" setShowResetModal={setShowResetModal} />}
    </div>
  );
}

const SidebarBtn = ({ active, onClick, icon, text }) => (<button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '15px', display: 'flex', alignItems: 'center', gap: '12px' }}>{icon} {text}</button>);
const DashboardCard = ({ title, count, icon, color, textColor }) => (<div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderLeft: `5px solid ${textColor}`, boxShadow: '0 4px 15px rgba(0,0,0,0.02)' }}><div><p style={{ margin: '0 0 5px 0', color: '#64748b', fontSize: '14px', fontWeight: 'bold' }}>{title}</p><h3 style={{ margin: 0, color: '#1e293b' }}>{count}</h3></div><div style={{ width: '50px', height: '50px', borderRadius: '50%', backgroundColor: color, display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '22px' }}>{icon}</div></div>);
const actionBtnStyle = { width: '100%', padding: '10px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' };
const activityCardStyle = { backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', border: '1px solid #e2e8f0' };
const logoutBtnStyle = { width: '100%', padding: '12px', backgroundColor: '#ef4444', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' };
